import{_ as n,l as r,o as e,c as l,v as t,p as h,x as i,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"WebAuthn / FIDO2","description":"","frontmatter":{"title":"WebAuthn / FIDO2","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/webauthn-fido2.md","filePath":"cs/webauthn-fido2.md","lastUpdated":1789023840000}'),A={name:"cs/webauthn-fido2.md"};function p(u,a,b,_,m,f){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="webauthn-fido2" tabindex="-1">WebAuthn / FIDO2 <a class="header-anchor" href="#webauthn-fido2" aria-label="Permalink to &quot;WebAuthn / FIDO2&quot;">​</a></h1><div class="epigraph"><p>WebAuthn 让浏览器把挑战交给认证器：私钥不出盒，站点拿到的是源绑定的公钥凭证。钓鱼站点换源就验不过，这是对共享口令模型的结构性修补。</p><footer>—— W3C Web Authentication；FIDO Alliance CTAP；对照 RFC 6238 仍只是第二因素</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/saml">SAML</a>仍常与口令 IdP 搭配。缺口是<strong>源绑定公钥</strong>：凭据属于 <code>https://example.com</code>，不是用户可粘贴的秘密。本课收登记与断言，不写破解认证器的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令可被钓鱼页收集。WebAuthn：RP ID、challenge、user verification、attestation（可选）。缺口是丢失设备与恢复流程——恢复若退回邮箱口令，钓鱼面回来。</p><h3 id="不是生物识别本身" tabindex="-1">不是生物识别本身 <a class="header-anchor" href="#不是生物识别本身" aria-label="Permalink to &quot;不是生物识别本身&quot;">​</a></h3><p>指纹/面容是认证器本地解锁。服务器只看见签名成功，不应存储生物模板。FAR/FRR 更后一课。</p><p><span class="marginnote">W3C WebAuthn Level 2/3。平台认证器与只安全密钥。本课不提供克隆密钥的指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分 ceremony：create 与 get。强调 challenge 防重放、origin 由浏览器填。服务器存公钥与计数器（克隆检测点名）。对照 TOTP：仍是共享秘密，可被钓鱼同时转发。</p>',12)),(e(),h(c,null,{default:i(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RP%5B%22%E7%AB%99%E7%82%B9%20origin%22%5D%20--%3E%20CH%5B%22challenge%22%5D%0A%20%20CH%20--%3E%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E5%99%A8%E7%AD%BE%22%5D%0A%20%20AUTH%20--%3E%20PUB%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%AA%8C%E5%85%AC%E9%92%A5%22%5D%0A%20%20ORIGIN%5B%22%E6%BA%90%E7%BB%91%E5%AE%9A%22%5D%20--%3E%20PUB%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份因素从「知道」转向「持有+本地解锁」。账户恢复、企业托管与备份密钥是治理，不是协议算术。下一课 TOTP 与 MFA：仍广泛部署的共享秘密第二因素。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CTAP hid 细节。TOTP 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SAML/OAuth 常仍站在口令上；WebAuthn 源绑定密钥。</li><li>私钥不出认证器；challenge 防重放。</li><li>恢复流程可能把钓鱼面请回来。</li><li>下一课 TOTP 与 MFA。</li><li>出处：W3C Web Authentication；FIDO CTAP；对照 RFC 6238。</li></ul>',8))])}const E=n(A,[["render",p]]);export{P as __pageData,E as default};
